 31	static void parse_args(int argc, char** argv, forward_service_config_t* cfg) {
 32	    for (int i = 1; i < argc; ++i) {
 33	        if (strcmp(argv[i], "--port") == 0 && (i + 1 < argc)) {
 34	            cfg->serial_port = argv[++i];
 35	        } else if (strcmp(argv[i], "--firmware-dir") == 0 && (i + 1 < argc)) {
 36	            cfg->firmware_dir = argv[++i];
 37	        } else if (strcmp(argv[i], "--baud") == 0 && (i + 1 < argc)) {
 38	            cfg->baud_rate = (uint32_t)strtoul(argv[++i], nullptr, 10);
 39	        } else if (strcmp(argv[i], "--dbus-custom") == 0 && (i + 1 < argc)) {
 40	            cfg->dbus_bus_type = AISOC_DBUS_BUS_CUSTOM;
 41	            cfg->dbus_custom_address = argv[++i];
 42	        } else if (strcmp(argv[i], "--dds-domain") == 0 && (i + 1 < argc)) {
 43	            cfg->dds_domain_id = (uint32_t)strtoul(argv[++i], nullptr, 10);
 44	        } else if (strcmp(argv[i], "--allow-offline-start") == 0) {
 45	            cfg->allow_offline_start = true;
 46	        }
 47	    }
