 50	/**
 51	 * @brief 处理启动节点探测结果；仅在显式 --allow-offline-start 时降级存活，默认保持 fail-fast。
 52	 * @param state Forward 服务运行时状态指针
 53	 * @param cfg 服务启动配置只读指针
 54	 * @param probe_st 启动探测返回值
 55	 * @return 0 表示可继续进入事件循环，非 0 表示应终止进程并返回该退出码
 56	 */
 57	static int handle_startup_probe(
 58	    forward_service_state_t* state,
 59	    const forward_service_config_t* cfg,
 60	    aisoc_fwd_status_t probe_st
 61	) {
 62	    if (probe_st == AISOC_FWD_OK) {
 63	        return 0;
 64	    }
 65	    if (!cfg->allow_offline_start) {
 66	        std::fprintf(stderr, "[FWD START] stage=NODE_PROBE error_code=%d\n", probe_st);
 67	        return 3;
 68	    }
 69	    // 生产自启降级模式：仅向首探失败节点发射离线信号，保留串口与在线节点自愈能力。
 70	    if (!state->cached_mc_ver_valid) {
 71	        forward_service_emit_link_state(state, 1U, false, "STARTUP_PROBE_FAILED");
 72	    }
 73	    if (!state->cached_th_ver_valid) {
 74	        forward_service_emit_link_state(state, 2U, false, "STARTUP_PROBE_FAILED");
 75	    }
 76	    std::fprintf(stderr, "[FWD START] stage=NODE_PROBE mode=OFFLINE_DEGRADED error_code=%d\n",
 77	                 probe_st);
 78	    std::fflush(stderr);
 79	    return 0;
 80	}
