 82	/**
 83	 * @brief Forward Service 守护进程主函数
 84	 * @param argc 参数数量
 85	 * @param argv 参数数组
 86	 * @return 0 表示正常退出，非 0 表示启动失败
 87	 */
 88	int main(int argc, char** argv) {
 89	    signal(SIGINT, signal_handler);
 90	    signal(SIGTERM, signal_handler);
 91	
 92	    forward_service_config_t cfg = {};
 93	    cfg.serial_port = AISOC_FWD_DEFAULT_PORT;
 94	    cfg.baud_rate = AISOC_FWD_DEFAULT_BAUD;
 95	    cfg.dbus_bus_type = AISOC_DBUS_BUS_SESSION;
 96	    parse_args(argc, argv, &cfg);
 97	
 98	    forward_service_state_t state;
 99	    aisoc_fwd_status_t st = forward_service_init(&cfg, &state);
100	    if (st != AISOC_FWD_OK) {
101	        return 1;
102	    }
103	
104	    st = forward_service_start(&state);
105	    if (st != AISOC_FWD_OK) {
106	        forward_service_stop(&state);
107	        return 2;
108	    }
109	
110	    // 默认启动保持 fail-fast 退出码 3；仅传入 --allow-offline-start 时允许断连降级存活。
111	    st = forward_service_probe_versions(&state, 200U);
112	    const int probe_rc = handle_startup_probe(&state, &cfg, st);
113	    if (probe_rc != 0) {
114	        forward_service_stop(&state);
115	        return probe_rc;
116	    }
117	    std::printf("[FORWARD] Service active on %s at %u baud (DDS domain %u)\n",
118	                cfg.serial_port, cfg.baud_rate, cfg.dds_domain_id);
119	    std::fflush(stdout);
120	
121	    while (g_keep_running && state.running) {
122	        bool dispatched = false;
123	        forward_service_dispatch(&state, 100, &dispatched);
124	    }
125	
126	    std::printf("[FORWARD] Shutting down service...\n");
127	    std::fflush(stdout);
128	    forward_service_stop(&state);
129	    return 0;
130	}
