392	def evaluate_scenario(ctx):
393	    """根据场景分支核验进程退出码、D-Bus 响应、日志标记与自愈闭环。"""
394	    scenario, daemon, log = ctx['scenario'], ctx['daemon'], ctx['log']
395	    deps, addr, env, model = ctx['deps'], ctx['address'], ctx['env'], ctx['model']
396	    if scenario == 'normal':
397	        res = dbus_call(deps, addr, env, ['org.aisoc.ForwardInterface.QueryVersion', 'byte:1', 'uint32:500'])
398	        return daemon.poll() is None and res.returncode == 0 and 'int32 0' in res.stdout and model.commands == [(2, 1), (3, 1), (2, 1)]
399	    if scenario == 'mc_boot':
400	        return daemon.poll() is None and 'mode=MC_BOOT_RECOVERY' in log and verify_mc_boot_readonly_and_recover(ctx)
401	    if scenario == 'offline_allow_mc_timeout':
402	        return daemon.poll() is None and 'mode=OFFLINE_DEGRADED' in log and verify_mc_timeout_recovery(ctx)
403	    if scenario == 'offline_allow_th_timeout':
404	        return daemon.poll() is None and 'mode=OFFLINE_DEGRADED' in log and verify_th_timeout_recovery(ctx)
405	    if scenario == 'offline_allow_both_timeout':
406	        return daemon.poll() is None and 'mode=OFFLINE_DEGRADED' in log and verify_both_timeout_recovery(ctx)
407	    if daemon.poll() is None:
408	        try:
409	            daemon.wait(timeout=0.5)
410	        except subprocess.TimeoutExpired:
411	            pass
412	    exp_code = 2 if scenario in ('open_failure', 'offline_allow_open_failure') else 3
413	    return daemon.poll() == exp_code and 'Service active' not in log
