134	def shutdown(context: dict) -> None:
135	    """按启动逆序优雅终止全部受管子进程组，超时后强杀回收。"""
136	    for _, process in reversed(context['processes']):
137	        if process.poll() is not None:
138	            continue
139	        try:
140	            os.killpg(process.pid, signal.SIGTERM)
141	        except ProcessLookupError:
142	            continue
143	        deadline = time.monotonic() + 3.0
144	        while process.poll() is None and time.monotonic() < deadline:
145	            pump(context, 0.05)
146	        if process.poll() is None:
147	            try:
148	                os.killpg(process.pid, signal.SIGKILL)
149	            except ProcessLookupError:
150	                pass
151	        process.wait(timeout=2)
152	    pump(context, 0)
