155	def launch_panel(context: dict) -> None:
156	    """若开启原生面板且二进制存在，检查帧缓冲占用后启动 HelixScreen。"""
157	    cfg = context['config']
158	    if not cfg.get('enable_panel', True):
159	        return
160	    fbdev = cfg.get('fbdev', '/dev/fb0')
161	    fb_owners = port_owners(fbdev)
162	    if fb_owners:
163	        raise RuntimeError('FB_ALREADY_OWNED:' + str(fb_owners))
164	    assets = resolve_root_path(cfg.get('panel_assets_dir', '/usr/share/printer-soc/helixscreen'))
165	    panel_bin = assets / 'bin/helix-screen'
166	    if not panel_bin.is_file():
167	        return
168	    panel_data = resolve_root_path(cfg.get('panel_runtime_dir', '/data/printer-soc/helix'))
169	    panel_data.mkdir(parents=True, exist_ok=True)
170	    context['env']['HELIX_DATA_DIR'] = str(panel_data)
171	    context['env']['HOME'] = str(panel_data)
172	    context['env']['AISOC_VERSION_FILE'] = str(resolve_root_path(cfg.get('version_file', '/etc/printer-soc/version.json')))
173	    # 生产面板使用相对 $ORIGIN RUNPATH 与真实版本 JSON，禁止附加 --test 或 demo 参数。
174	    launch(context, 'panel', [str(panel_bin)], cwd=assets)
