177	def launch_backend_daemons(context: dict, trace: Path, bus_addr: str) -> None:
178	    """启动 Forward、DeviceManager 与可选 Gateway 后台服务。"""
179	    runtime, bundle, cfg = context['runtime'], context['bundle'], context['config']
180	    common = ['--dbus-custom', bus_addr, '--dds-domain', str(cfg['dds_domain'])]
181	    forward = [str(bundle / 'bin/forward_service_daemon'), '--port', cfg['uart'],
182	               '--baud', str(cfg['baud']), '--firmware-dir', str(runtime / 'firmware')] + common
183	    if cfg.get('allow_offline_start', True):
184	        forward.append('--allow-offline-start')
185	    if trace:
186	        forward = [str(trace), '-f', '-ttt', '-xx', '-yy', '-s', '2048', '-o',
187	                   str(runtime / 'serial.strace'), '-e', 'trace=read,write,openat,close,ioctl'] + forward
188	    if not context['offline']:
189	        launch(context, 'forward', forward)
190	        wait_for(context, 'forward', 'Service active')
191	    launch(context, 'device_manager', [str(bundle / 'bin/device_manager_daemon')] + common)
192	    wait_for(context, 'device_manager', 'Service active')
193	    if cfg.get('enable_gateway', False):
194	        with socket.socket() as available:
195	            available.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
196	            available.bind(('0.0.0.0', cfg['http_port']))
197	        launch(context, 'gateway', [str(bundle / 'bin/ui-gateway'), '--dbus-conf', bus_addr,
198	                                    '--dds-domain', str(cfg['dds_domain']),
199	                                    '--port', str(cfg['http_port']),
200	                                    '--static-dir', str(bundle / 'static-empty')])
