203	def launch_services(context: dict, trace: Path) -> None:
204	    """校验硬件资源独占后按依赖顺序拉起 D-Bus、后台服务与原生面板。"""
205	    bundle, cfg = context['bundle'], context['config']
206	    if not context['offline']:
207	        owners = port_owners(cfg['uart'])
208	        if owners:
209	            raise RuntimeError('UART_ALREADY_OWNED:' + str(owners))
210	    launch(context, 'dbus', [str(bundle / 'bin/dbus-daemon'), '--nofork',
211	                             '--print-address=1', '--config-file=' + str(bundle / 'config/session.conf')])
212	    address = wait_for(context, 'dbus', 'unix:').strip()
213	    context['state']['bus_address'] = address
214	    context['env']['DBUS_SESSION_BUS_ADDRESS'] = address
215	    context['env']['AISOC_DBUS_ADDRESS'] = address
216	    launch_backend_daemons(context, trace, address)
217	    launch_panel(context)
